import type { QuizQuestion } from "./types";

export type ThermoLab = "gas" | "collision" | "freedom" | "work" | "paths" | "balance" | "processes" | "heating" | "entropy" | "engine" | "fridge";
export type Block = { text: string } | { latex: string } | { bullets: string[] } | { headers: string[]; rows: string[][] };
export interface ThermoSection {
  id: string; title: string; observation: string;
  prediction?: QuizQuestion; lab?: ThermoLab; blocks: Block[]; note: string;
}
export interface ThermoLesson {
  intro: string; thread: string; sections: ThermoSection[]; recap: string[]; quiz: QuizQuestion[]; problems: string[];
}
const t = (text: string): Block => ({ text });
const f = (latex: string): Block => ({ latex });
const list = (...bullets: string[]): Block => ({ bullets });
export function question(question: string, correct: string, why: string, wrong: string, wrongWhy: string): QuizQuestion {
  return { question, options: [{ text: correct, correct: true, why }, { text: wrong, correct: false, why: wrongWhy }], explanation: why };
}
const q = question;
const raw = String.raw;

